/*
 * BME280 Weather Station — I2C
 *
 * Wiring:
 *   VCC -> 3.3V (or 5V)
 *   GND -> GND
 *   SCL -> A5
 *   SDA -> A4
 *
 * Reads temperature, humidity, and pressure via raw registers.
 * No external library required.
 *
 * Drag the Temp / Hum / hPa sliders on the sensor
 * to simulate different environmental conditions.
 */

#include <Wire.h>

#define BME_ADDR 0x76

// Calibration storage
unsigned int dig_T1;
int dig_T2, dig_T3;
unsigned int dig_P1;
int dig_P2, dig_P3, dig_P4, dig_P5;
int dig_P6, dig_P7, dig_P8, dig_P9;
int dig_H3;
int dig_H4, dig_H5;
int dig_H6;

long t_fine;

unsigned char readReg(unsigned char reg) {
  Wire.beginTransmission(BME_ADDR);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(BME_ADDR, (unsigned char)1);
  return Wire.read();
}

void readRegs(unsigned char reg, unsigned char *buf, unsigned char len) {
  Wire.beginTransmission(BME_ADDR);
  Wire.write(reg);
  Wire.endTransmission(false);
  Wire.requestFrom(BME_ADDR, len);
  for (unsigned char i = 0; i < len; i++) buf[i] = Wire.read();
}

void writeReg(unsigned char reg, unsigned char val) {
  Wire.beginTransmission(BME_ADDR);
  Wire.write(reg);
  Wire.write(val);
  Wire.endTransmission();
}

void readCalibration() {
  unsigned char buf[26];
  readRegs(0x88, buf, 26);
  dig_T1 = buf[1] << 8 | buf[0];
  dig_T2 = buf[3] << 8 | buf[2];
  dig_T3 = buf[5] << 8 | buf[4];
  dig_P1 = buf[7] << 8 | buf[6];
  dig_P2 = buf[9] << 8 | buf[8];
  dig_P3 = buf[11] << 8 | buf[10];
  dig_P4 = buf[13] << 8 | buf[12];
  dig_P5 = buf[15] << 8 | buf[14];
  dig_P6 = buf[17] << 8 | buf[16];
  dig_P7 = buf[19] << 8 | buf[18];
  dig_P8 = buf[21] << 8 | buf[20];
  dig_P9 = buf[23] << 8 | buf[22];
  unsigned char h1 = readReg(0xA1);
  unsigned char e1buf[7];
  readRegs(0xE1, e1buf, 7);
  dig_H3 = e1buf[1] << 8 | e1buf[0];
  dig_H4 = (e1buf[2] << 4) | (e1buf[3] & 0x0F);
  if (dig_H4 > 2047) dig_H4 -= 4096;
  dig_H5 = (e1buf[4] >> 4) | (e1buf[5] << 4);
  if (dig_H5 > 2047) dig_H5 -= 4096;
  dig_H6 = (int)e1buf[6];
}

float readTemperature() {
  unsigned char buf[3];
  readRegs(0xFA, buf, 3);
  long adc_T = ((long)buf[0] << 12) | ((long)buf[1] << 4) | (buf[2] >> 4);
  long var1 = (((adc_T >> 3) - ((long)dig_T1 << 1)) * ((long)dig_T2)) >> 11;
  long var2 = (((((adc_T >> 4) - ((long)dig_T1)) * ((adc_T >> 4) - ((long)dig_T1))) >> 12) * ((long)dig_T3)) >> 14;
  t_fine = var1 + var2;
  return (t_fine * 5 + 128) >> 8;
}

float readPressure() {
  unsigned char buf[3];
  readRegs(0xF7, buf, 3);
  long adc_P = ((long)buf[0] << 12) | ((long)buf[1] << 4) | (buf[2] >> 4);
  long long var1 = ((long long)t_fine) - 128000;
  long long var2 = var1 * var1 * (long long)dig_P6;
  var2 = var2 + ((var1 * (long long)dig_P5) << 17);
  var2 = var2 + (((long long)dig_P4) << 35);
  var1 = ((var1 * var1 * (long long)dig_P3) >> 8) + ((var1 * (long long)dig_P2) << 12);
  var1 = (((((long long)1) << 47) + var1)) * ((long long)dig_P1) >> 33;
  if (var1 == 0) return 0;
  long long p = 1048576 - adc_P;
  p = (((p << 31) - var2) * 3125) / var1;
  var1 = (((long long)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
  var2 = (((long long)dig_P8) * p) >> 19;
  p = ((p + var1 + var2) >> 8) + (((long long)dig_P7) << 4);
  return (float)p / 256.0;
}

float readHumidity() {
  unsigned char buf[2];
  readRegs(0xFD, buf, 2);
  long adc_H = ((long)buf[0] << 8) | (long)buf[1];
  long h1 = (t_fine - 76800);
  if (h1 == 0) return 0;
  h1 = ((((adc_H << 14) - (((long)dig_H4) << 20) - (((long)dig_H5) * h1)) + 16384) >> 15);
  long h2 = (((((h1 * ((long)dig_H6)) >> 10) * ((h1 * ((long)dig_H3)) >> 11)) >> 10) + 32768) >> 15;
  h1 = (h1 * ((long)61035156)) >> 11;
  h1 = (h2 - (((((h1 * ((long)15712))) >> 10) * ((long)32768))) >> 14);
  if (h1 < 0) h1 = 0;
  if (h1 > 419430400) h1 = 419430400;
  return (float)(h1 >> 12) / 1024.0;
}

void setup() {
  Wire.begin();
  Serial.begin(115200);
  Serial.println("BME280 Weather Station");
  Serial.println("----------------------");

  unsigned char id = readReg(0xD0);
  Serial.print("Chip ID: 0x");
  Serial.println(id, HEX);

  readCalibration();

  writeReg(0xF2, 0x01);
  writeReg(0xF4, 0x27);
  writeReg(0xF5, 0xA0);

  Serial.println("Ready. Drag sliders to change values.");
  Serial.println("----------------------");
}

void loop() {
  float tempC   = readTemperature();
  float humPct  = readHumidity();
  float presHpa = readPressure() / 100.0;

  Serial.print("Temp:      ");
  Serial.print(tempC, 1);
  Serial.println(" C");

  Serial.print("Humidity:  ");
  Serial.print(humPct, 1);
  Serial.println(" %");

  Serial.print("Pressure:  ");
  Serial.print(presHpa, 1);
  Serial.println(" hPa");

  Serial.println("----------------------");
  delay(2000);
}
